CREATE TABLE transport_providers(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`user_id` bigint  NOT NULL,`company_name` varchar(255)  NOT NULL,`contact_person` varchar(255)  NOT NULL,`contact_phone` varchar(20)  NOT NULL,`contact_email` varchar(255)  NULL,`service_areas` text  NOT NULL COMMENT 'JSON array of states/districts served',`vehicle_types` text  NOT NULL COMMENT 'JSON array: truck, tempo, mini_truck, specialized_livestock',`livestock_specialization` text  NULL COMMENT 'JSON array: cattle, goat, sheep, poultry, buffalo',`base_rate_per_km` DECIMAL(10,2)  NOT NULL COMMENT 'Base rate in INR per kilometer',`minimum_charge` DECIMAL(10,2)  NOT NULL COMMENT 'Minimum charge in INR',`insurance_available` TINYINT(1)  DEFAULT 0,`insurance_rate_percentage` DECIMAL(5,2)  NULL COMMENT 'Insurance cost as percentage of animal value',`max_capacity_animals` INT  NOT NULL COMMENT 'Maximum number of animals per trip',`rating` DECIMAL(3,2)  DEFAULT 0 COMMENT 'Average rating 0-5',`total_ratings` INT  DEFAULT 0,`completed_transports` INT  DEFAULT 0,`verified` TINYINT(1)  DEFAULT 0,`verification_documents` text  NULL COMMENT 'JSON array of S3 document URLs',`license_number` varchar(100)  NULL,`status` varchar(50)  DEFAULT 'active' COMMENT 'active, inactive, suspended')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;